"""Interfaces for data module to reduce coupling."""

from abc import ABC, abstractmethod
import torch.utils.data


class IDataLoader(ABC):
    """Interface for data loaders."""

    @abstractmethod
    def load_data(self):
        """Return the dataset instance."""
        pass

    @abstractmethod
    def __len__(self):
        """Return the number of batches."""
        pass

    @abstractmethod
    def __iter__(self):
        """Return an iterator over batches."""
        pass


class IDatasetFactory(ABC):
    """Interface for dataset factories."""

    @abstractmethod
    def get_by_name(self, dataset_name, *args, **kwargs):
        """Return a dataset instance by name."""
        pass


class IDataset(ABC):
    """Interface for datasets."""

    @abstractmethod
    def __len__(self):
        """Return the number of samples."""
        pass

    @abstractmethod
    def __getitem__(self, idx):
        """Return a sample at index idx."""
        pass

    @abstractmethod
    def name(self):
        """Return dataset name."""
        pass
